```php
public function morphTo($name = null, $type = null, $id = null, $ownerKey = null)
{
    $name = $name ?: $this->getRelationName(...);

    [$type, $id] = $this->getMorphs(Str::snake($name), $type, $id);

    // If the type value is null it is probably safe to assume we're eager loading
    // the relationship. When that is the case we will pass in a dummy query as
    // there are multiple types in the morph and we can't use single queries.
    if (is_null($class = $this->getAttributeFromArray($type))) {
        return $this->morphEagerTo($name, $type, $id, $ownerKey);
    }

    // If we are not eager loading the relationship we will essentially treat this
    // relation as a belongsTo one since morphTo extends that class and on this
    // relation we get the single model for the given type and id.
    return $this->morphInstanceTo($class, $name, $type, $id, $ownerKey);
}
```

